#include "native/providers/gdn/absolute_dot_bound.h"
#include "native/providers/gdn/sm121_exp2_table.h"
#include "native/providers/moe_accumulator/q1_moe_hawkeye_bf16_accumulator.h"
#include <algorithm>
#include <cassert>
#include <cstdio>
#include <fstream>
#include <string>
#include <vector>
namespace norm=qrt_fla_absolute_dot;
namespace bits=qrt_sm121_pv_bound;
namespace consumer=qrt_fla_consumer_interval;
namespace original=qrt_q1_moe_hawkeye;
static uint32_t seed=0x3957169u;
static uint32_t next(){seed^=seed<<13u;seed^=seed>>17u;return seed^=seed<<5u;}
template<class T>static std::vector<T> read(const std::string& file,size_t count){
    std::ifstream input(file,std::ios::binary|std::ios::ate);
    assert(input && input.tellg()==std::streamoff(count*sizeof(T)));
    std::vector<T> out(count);input.seekg(0);
    input.read(reinterpret_cast<char*>(out.data()),count*sizeof(T));assert(input.good());return out;
}
static float from(uint16_t x){return bits::value(uint32_t(x)<<16u);}
static norm::Norm summarize(const uint16_t* row){norm::Row r;for(unsigned i=0;i<128;++i)norm::include(r,row[i]);return norm::finish(r);}
static float dot(const uint16_t* a,const uint16_t* b,unsigned count){
    original::Value carry{0u,-133,false};
    for(unsigned base=0;base<count;base+=16u){
        original::Value terms[17];terms[0]=carry;
        for(unsigned i=0;i<16;++i)terms[i+1]=original::multiply_bf16(a[base+i],b[base+i],-133);
        carry=original::group_sum<26,-133>(terms,17u);
    }
    return original::value_to_float(original::group_sum<26,-133>(&carry,1u));
}
int main(int argc,char** argv){
    assert(argc==3);const std::string root=argv[1];
    const auto table=read<unsigned char>(argv[2],qrt_sm121_exp2::table_bytes);
    assert(qrt_sm121_exp2::valid_layout(table.data(),table.size()));
    const auto w=read<uint16_t>(root+"/full-w-bf16.bin",size_t(7169)*4096);
    const auto u=read<uint16_t>(root+"/full-u-bf16.bin",w.size());
    const auto vn=read<uint16_t>(root+"/full-v-new-bf16.bin",w.size());
    const auto out=read<uint16_t>(root+"/full-output-bf16.bin",w.size());
    const auto q=read<uint16_t>(root+"/full-q-normalized-bf16.bin",size_t(7169)*2048);
    const auto k=read<uint16_t>(root+"/full-k-normalized-bf16.bin",q.size());
    const auto h=read<uint16_t>(root+"/full-chunk-state-bf16.bin",size_t(113)*524288);
    const auto g=read<float>(root+"/full-g-cumsum-f32.bin",size_t(7169)*32);
    auto exp=[&](float x){return qrt_sm121_exp2::evaluate(table.data(),consumer::multiply(x,1.4426950408889634074f));};
    std::vector<norm::Norm> wn(w.size()/128),qn(q.size()/128),hn(h.size()/128);
    size_t invalid_rows=0;
    for(size_t i=0;i<wn.size();++i){wn[i]=summarize(w.data()+i*128);invalid_rows+=!wn[i].count;}
    for(size_t i=0;i<qn.size();++i){qn[i]=summarize(q.data()+i*128);invalid_rows+=!qn[i].count;}
    for(size_t i=0;i<hn.size();++i){hn[i]=summarize(h.data()+i*128);invalid_rows+=!hn[i].count;}
    size_t admitted=0,unscaled=0,zero=0,nonzero=0;
    for(unsigned chunk=0;chunk<113;++chunk){
        const unsigned start=chunk*64,end=std::min(start+64,7169u);size_t accepted=0;
        for(unsigned token=start;token<end;++token)for(unsigned head=0;head<32;++head){
            const float decay=exp(consumer::subtract(g[size_t(end-1)*32+head],g[size_t(token)*32+head]));
            for(unsigned col=0;col<128;++col){
                const size_t index=(size_t(token)*32+head)*128+col;
                const auto checkpoint=hn[(size_t(chunk)*32+head)*128+col];
                const auto envelope=norm::enclose(wn[size_t(token)*32+head],checkpoint);
                const float value=from(u[index]);uint16_t a=0xa5a5,b=a;
                if(qrt_sm121_projection_interval::valid(envelope)){
                    uint16_t unused=0;
                    unscaled+=consumer::rounded({consumer::subtract(value,envelope.upper),consumer::subtract(value,envelope.lower)},&unused);
                }
                if(consumer::residual(envelope,value,decay,&a,&b)){
                    assert(a==vn[index]);++accepted;++admitted;
                    if(checkpoint.maximum==0.0f)++zero;else ++nonzero;
                }else assert(a==0xa5a5 && b==0xa5a5);
            }
        }
        std::printf("{\"type\":\"chunk\",\"chunk\":%u,\"cells\":%u,\"both_residuals_admitted\":%zu}\n",chunk,(end-start)*4096,accepted);
    }
    size_t sample_state=0,sample_output=0,reference_dots=0,invalid_dots=0;
    for(unsigned attempt=0;attempt<65536;++attempt){
        const unsigned token=next()%7169,head=next()%32,col=next()%128;
        const unsigned start=token/64*64,end=std::min(start+64,7169u);
        const size_t index=(size_t(token)*32+head)*128+col;
        const size_t hi=(size_t(token/64)*32+head)*128+col;
        const auto* checkpoint=h.data()+hi*128;
        const float decay=exp(consumer::subtract(g[size_t(end-1)*32+head],g[size_t(token)*32+head]));
        for(unsigned op=0;op<2;++op){
            const size_t li=op?size_t(token)*16+head/2:size_t(token)*32+head;
            const uint16_t* left=(op?q.data():w.data())+li*128;
            const float actual=dot(left,checkpoint,128);++reference_dots;
            const auto envelope=norm::enclose(op?qn[li]:wn[li],hn[hi]);
            if(!qrt_sm121_projection_interval::valid(envelope)){++invalid_dots;continue;}
            assert(actual>=envelope.lower && actual<=envelope.upper);
            if(!op){
                const float difference=consumer::subtract(from(u[index]),actual);
                assert(bits::bf16(difference)==vn[index]);
                uint16_t a=0xa5a5,b=a;
                if(consumer::residual(envelope,from(u[index]),decay,&a,&b)){
                    assert(a==bits::bf16(difference) && b==bits::bf16(consumer::multiply(difference,decay)));++sample_state;
                }
            }else if(attempt<4096){
                uint16_t scores[64]{},values[64]{};
                for(unsigned source=0;source<=token%64;++source){
                    const float score=dot(left,k.data()+(size_t(start+source)*16+head/2)*128,128);
                    const float gate=exp(consumer::subtract(g[size_t(token)*32+head],g[size_t(start+source)*32+head]));
                    scores[source]=bits::bf16(consumer::multiply(score,gate));
                    values[source]=vn[(size_t(start+source)*32+head)*128+col];
                }
                const float local=dot(scores,values,64),gate=exp(g[size_t(token)*32+head]);
                const float prior=consumer::multiply(consumer::multiply(actual,gate),0.08838834764831845f);
                const auto expected=bits::bf16(std::fma(local,0.08838834764831845f,prior));
                assert(expected==out[index]);uint16_t result=0xa5a5;
                if(consumer::output(envelope,{local,local},gate,&result)){assert(result==expected);++sample_output;}
                else assert(result==0xa5a5);
            }
        }
    }
    std::printf("{\"type\":\"summary\",\"cells\":%zu,\"unscaled_residual_admitted\":%zu,\"both_residuals_admitted\":%zu,\"zero_state_admitted\":%zu,\"nonzero_state_admitted\":%zu,\"invalid_rows\":%zu,\"original_dots\":%zu,\"invalid_sampled_dots\":%zu,\"sampled_state_consumers\":65536,\"sampled_state_admitted\":%zu,\"sampled_output_consumers\":4096,\"sampled_output_admitted\":%zu,\"bound_violations\":0,\"original_bf16_mismatches\":0}\n",w.size(),unscaled,admitted,zero,nonzero,invalid_rows,reference_dots,invalid_dots,sample_state,sample_output);
}
